#!/usr/bin/env python3
import sys, os, io, csv, json, gzip
from datetime import datetime, timezone, timedelta, date
from decimal import Decimal, ROUND_HALF_UP
from zoneinfo import ZoneInfo


def read_text(path):
    with open(path, 'rb') as f:
        data = f.read()
    if data[:2] == b'\x1f\x8b':
        data = gzip.decompress(data)
    return data.decode('utf-8-sig')


def lines_of(text):
    return [l for l in text.replace('\r\n', '\n').replace('\r', '\n').split('\n') if l.strip() != '']


def local_to_ts(tz, naive, dst=None):
    """naive local datetime -> epoch seconds. dst: True/False/None picks repeated time."""
    a = naive.replace(tzinfo=tz, fold=0)
    b = naive.replace(tzinfo=tz, fold=1)
    if a.utcoffset() != b.utcoffset() and dst is not None:
        for c in (a, b):
            if bool(c.dst()) == dst:
                return int(c.timestamp())
    return int(a.timestamp())


def std_offset(tz, ts):
    y = datetime.fromtimestamp(ts, timezone.utc).year
    offs = [tz.utcoffset(datetime(y, m, 1)) for m in (1, 7)]
    return int(min(offs).total_seconds())


def norm_id(v):
    if isinstance(v, bool):
        return str(v)
    if isinstance(v, float):
        v = int(v)
    return str(v)


def parse_abbr(text, tz):
    out = []
    header = None
    for ln in lines_of(text):
        row = next(csv.reader([ln]))
        row = [c.strip() for c in row]
        if 'Badge' in row and 'Punch' in row:
            header = row
            continue
        if header is None:
            continue
        r = dict(zip(header, row))
        d = datetime.strptime(r['Date'], '%m/%d/%Y')
        t = r['Time'].strip().upper()
        ampm = None
        if t.endswith('AM') or t.endswith('PM'):
            ampm = t[-2:]
            t = t[:-2].strip()
        h, m, s = [int(x) for x in t.split(':')]
        if ampm:
            h = h % 12 + (12 if ampm == 'PM' else 0)
        naive = d.replace(hour=h, minute=m, second=s)
        z = r.get('Zone', '').upper()
        dst = True if z.endswith('DT') else (False if z.endswith('ST') else None)
        out.append((r['Record'], r['Badge'], r['Punch'].upper(), local_to_ts(tz, naive, dst)))
    return out


def parse_epoch(text):
    out = []
    schema = 1
    for ln in lines_of(text):
        o = json.loads(ln)
        if 'schema' in o and 'id' not in o and 'punch_id' not in o:
            schema = o['schema']
            continue
        if o.get('heartbeat'):
            continue
        if schema == 2:
            if 'punch_id' not in o:
                continue
            out.append((norm_id(o['punch_id']), o['employee'], o['direction'].upper(),
                        int(o['epoch_ms']) // 1000))
        else:
            if 'id' not in o:
                continue
            ts = int(o['ts_ms']) // 1000 if 'ts_ms' in o else int(o['ts'])
            out.append((norm_id(o['id']), o['emp'], o['dir'].upper(), ts))
    return out


def parse_offset(text):
    out = []
    header = None
    for ln in lines_of(text):
        row = next(csv.reader([ln], delimiter=';'))
        if 'punch_id' in row and 'timestamp' in row:
            header = row
            continue
        if header is None:
            continue
        r = dict(zip(header, row))
        ts = int(datetime.fromisoformat(r['timestamp']).timestamp())
        ev = r['event'].lower()
        out.append((r['punch_id'], r['employee'], 'IN' if ev.endswith('in') else 'OUT', ts))
    return out


def parse_legacy(text, tz):
    out = []
    off = None
    for ln in text.replace('\r\n', '\n').split('\n'):
        if not ln.strip():
            continue
        k = ln[0]
        if k == 'H':
            o = ln[13:18].strip()
            if len(o) == 5 and o[0] in '+-':
                sec = (int(o[1:3]) * 3600 + int(o[3:5]) * 60)
                off = -sec if o[0] == '-' else sec
            else:
                off = None
        elif k == 'D':
            pid = ln[1:9]
            badge = ln[9:15].strip()
            dirc = ln[15]
            dt = datetime.strptime(ln[16:30], '%Y%m%d%H%M%S')
            as_utc = int(dt.replace(tzinfo=timezone.utc).timestamp())
            if off is None:
                o = std_offset(tz, as_utc)
                ts = as_utc - o
                # recheck with the offset at actual instant
                o = std_offset(tz, ts)
                ts = as_utc - o
            else:
                ts = as_utc - off
            out.append((pid, 'E' + badge, 'IN' if dirc == 'I' else 'OUT', ts))
    return out


def parse_de(text, tz):
    out = []
    header = None
    for ln in lines_of(text):
        row = [c.strip() for c in ln.split('\t')]
        if 'Ausweis' in row:
            header = row
            continue
        if header is None:
            continue
        r = dict(zip(header, row))
        d = datetime.strptime(r['Datum'] + ' ' + r['Uhrzeit'], '%d.%m.%Y %H:%M')
        z = r.get('Zeitzone', '').upper()
        dst = True if z == 'MESZ' else (False if z == 'MEZ' else None)
        out.append((r['Nr'], r['Ausweis'], 'IN' if r['Buchung'].upper() == 'K' else 'OUT',
                    local_to_ts(tz, d, dst)))
    return out


def parse_localcsv(text, tz):
    out = []
    header = None
    for ln in lines_of(text):
        row = [c.strip() for c in next(csv.reader([ln]))]
        if 'employee_id' in row and 'local_time' in row:
            header = row
            continue
        if header is None:
            continue
        r = dict(zip(header, row))
        d = datetime.strptime(r['local_time'], '%Y-%m-%d %H:%M:%S')
        out.append((r['punch_ref'], r['employee_id'], r['direction'].upper(), local_to_ts(tz, d, True)))
    return out


def parse_localjsonl(text, tz):
    out = []
    for ln in lines_of(text):
        o = json.loads(ln)
        p = o.get('punch')
        if not isinstance(p, dict):
            continue
        d = datetime.strptime(p['at'], '%Y-%m-%d %H:%M:%S')
        out.append((norm_id(p['id']), p['badge'], p['type'].upper(), local_to_ts(tz, d, True)))
    return out


def parse_ts(s):
    return datetime.fromisoformat(s.strip().replace('Z', '+00:00'))


def main(inp, outp):
    period = json.load(open(os.path.join(inp, 'period.json')))
    pstart = date.fromisoformat(period['start'])
    pend = date.fromisoformat(period['end'])
    cutoff = parse_ts(period['corrections_cutoff'])
    if cutoff.tzinfo is None:
        cutoff = cutoff.replace(tzinfo=timezone.utc)

    sites = {}
    with open(os.path.join(inp, 'sites.csv'), encoding='utf-8-sig', newline='') as f:
        for r in csv.DictReader(f):
            sites[r['site'].strip()] = (ZoneInfo(r['timezone'].strip()), r['format'].strip())
    employees = {}
    with open(os.path.join(inp, 'employees.csv'), encoding='utf-8-sig', newline='') as f:
        for r in csv.DictReader(f):
            employees[r['employee_id'].strip()] = r['home_site'].strip()
    rates = {}
    with open(os.path.join(inp, 'rates.csv'), encoding='utf-8-sig', newline='') as f:
        for r in csv.DictReader(f):
            rates.setdefault(r['employee_id'].strip(), []).append(
                (date.fromisoformat(r['effective_from'].strip()), Decimal(r['hourly_rate'].strip())))
    for v in rates.values():
        v.sort()

    # 1. collect
    punches = {}   # (site, id) -> [emp, dir, ts]
    ever = set()
    for site, (tz, fmt) in sites.items():
        d = os.path.join(inp, 'exports', site)
        if not os.path.isdir(d):
            continue
        for root, _, files in os.walk(d):
            for fn in sorted(files):
                text = read_text(os.path.join(root, fn))
                if fmt == 'abbr-csv':
                    rows = parse_abbr(text, tz)
                elif fmt == 'epoch-jsonl':
                    rows = parse_epoch(text)
                elif fmt == 'offset-csv':
                    rows = parse_offset(text)
                elif fmt == 'legacy-fixed':
                    rows = parse_legacy(text, tz)
                elif fmt == 'de-tsv':
                    rows = parse_de(text, tz)
                elif fmt == 'local-csv':
                    rows = parse_localcsv(text, tz)
                elif fmt == 'local-jsonl':
                    rows = parse_localjsonl(text, tz)
                else:
                    raise SystemExit('unknown format ' + fmt)
                for pid, emp, dr, ts in rows:
                    k = (site, pid)
                    ever.add(k)
                    if k not in punches:
                        punches[k] = [emp, dr, ts]

    # 2. corrections
    corr = []
    cdir = os.path.join(inp, 'corrections')
    if os.path.isdir(cdir):
        for root, _, files in os.walk(cdir):
            for fn in files:
                text = read_text(os.path.join(root, fn))
                for r in csv.DictReader(io.StringIO(text)):
                    r = {k.strip(): (v or '').strip() for k, v in r.items() if k}
                    if not r.get('correction_id'):
                        continue
                    corr.append(r)
    for r in corr:
        r['_t'] = parse_ts(r['issued_at']).astimezone(timezone.utc)
    corr.sort(key=lambda r: (r['_t'], r['correction_id']))
    voided = set()
    applied = 0
    for r in corr:
        if r['_t'] > cutoff:
            continue
        site = r['site']
        fmt = sites.get(site, (None, ''))[1]
        pid = r['punch_id']
        if fmt == 'local-jsonl' and pid.isdigit():
            pid = str(int(pid))
        k = (site, pid)
        a = r['action'].lower()
        if a == 'void':
            if k in punches:
                del punches[k]
                voided.add(k)
                applied += 1
        elif a == 'set':
            if k in punches:
                punches[k][2] = int(parse_ts(r['time']).timestamp())
                applied += 1
        elif a == 'add':
            if k not in punches and k not in ever and k not in voided:
                punches[k] = [r['employee'], r['type'].upper(), int(parse_ts(r['time']).timestamp())]
                ever.add(k)
                applied += 1

    byemp = {}
    for (site, pid), (emp, dr, ts) in punches.items():
        if emp in employees:
            byemp.setdefault(emp, []).append((ts, 0 if dr == 'OUT' else 1, site, pid, dr))

    def rnd(ts, tz):
        off = int(tz.utcoffset(datetime.fromtimestamp(ts, timezone.utc)).total_seconds())
        r = (ts + off) % 360
        return ts + (360 - r if r >= 180 else -r)

    stats = {e: dict(shifts=0, paid=0, ot=0, night=0, gross=Decimal(0)) for e in employees}
    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0)

    def night_before(x):
        return (x // 1440) * 480 + min(x % 1440, 360) + max(0, x % 1440 - 1320)

    def night_minutes(a, b, tz):
        oa = int(tz.utcoffset(datetime.fromtimestamp(a, timezone.utc)).total_seconds())
        ob = int(tz.utcoffset(datetime.fromtimestamp(b, timezone.utc)).total_seconds())
        if oa == ob:
            la = (a + oa) // 60
            lb = (b + oa) // 60
            return night_before(lb) - night_before(la)
        n = 0
        t = a
        while t < b:
            o = int(tz.utcoffset(datetime.fromtimestamp(t, timezone.utc)).total_seconds())
            h = ((t + o) // 60) % 1440
            if h < 360 or h >= 1320:
                n += 1
            t += 60
        return n

    for emp, lst in byemp.items():
        hz = sites[employees[emp]][0]
        lst.sort(key=lambda x: (x[0], x[1], x[2], x[3]))
        kept = []
        last = None
        for ts, _, site, pid, dr in lst:
            rts = rnd(ts, sites[site][0])
            wd = datetime.fromtimestamp(rts, hz).date()
            if last is not None and last[1] == dr and ts - last[0] <= 300:
                if pstart <= wd <= pend:
                    exc['duplicates_dropped'] += 1
                continue
            last = (ts, dr)
            kept.append((rts, dr, site, wd))
        shifts = []
        cur = None
        def open_(c):
            if pstart <= c[3] <= pend:
                exc['open_shifts'] += 1
        for p in kept:
            if p[1] == 'IN':
                if cur is not None:
                    open_(cur)
                cur = p
            else:
                if cur is not None and p[0] - cur[0] <= 16 * 3600:
                    shifts.append((cur, p))
                    cur = None
                else:
                    if cur is not None:
                        open_(cur)
                        cur = None
                    if pstart <= p[3] <= pend:
                        exc['orphan_outs'] += 1
        if cur is not None:
            open_(cur)
        shifts = [s for s in shifts if pstart <= s[0][3] <= pend]
        shifts.sort(key=lambda s: s[0][0])
        daily = {}
        weekly = {}
        st = stats[emp]
        for i, o in shifts:
            worked = max(0, (o[0] - i[0]) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_minutes(i[0], o[0], sites[i[2]][0]), paid)
            wd = i[3]
            used = daily.get(wd, 0)
            dot = max(0, used + paid - 480) - max(0, used - 480)
            daily[wd] = used + paid
            wk = wd - timedelta(days=wd.weekday())
            nd = paid - dot
            wu = weekly.get(wk, 0)
            wot = max(0, wu + nd - 2400) - max(0, wu - 2400)
            weekly[wk] = wu + nd
            ot = dot + wot
            reg = paid - ot
            rate = Decimal(0)
            rl = rates.get(emp, [])
            for ef, rv in rl:
                if ef <= wd:
                    rate = rv
            if not rate and rl and all(ef > wd for ef, _ in rl):
                rate = rl[0][1]
            pay = rate * (Decimal(reg) + Decimal('1.5') * ot) / 60 + rate * Decimal('0.15') * night / 60
            st['shifts'] += 1
            st['paid'] += paid
            st['ot'] += ot
            st['night'] += night
            st['gross'] += pay

    res_emp = {}
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    tg = Decimal(0)
    for e in sorted(employees):
        s = stats[e]
        g = s['gross'].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        res_emp[e] = dict(shifts=s['shifts'], paid_minutes=s['paid'], overtime_minutes=s['ot'],
                          night_minutes=s['night'], gross=format(g, 'f'))
        tot['shifts'] += s['shifts']
        tot['paid_minutes'] += s['paid']
        tot['overtime_minutes'] += s['ot']
        tot['night_minutes'] += s['night']
        tg += g
    tot['gross'] = format(tg, 'f')
    exc['corrections_applied'] = applied
    out = dict(period=dict(start=period['start'], end=period['end']), employees=res_emp,
               exceptions=exc, totals=tot)
    with open(outp, 'w') as f:
        json.dump(out, f, indent=1)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
